// expand groups with repeats into multiple groups
function expandRepeats(groups: TurnGroupInfo[]) {
    const newGroups: TurnGroupInfo[] = [];
    for (let g of groups) {
        for (let i=0; i<(g.repeats || 1); i++) {
            newGroups.push(
                {
                    ...g,
                    repeats: 1,
                }
            );
        }
    }
    return newGroups;
}

// expand host moves to include NPC actions
function expandNPCMoves(groups: TurnGroupInfo[], npcIDs: number[]) {
    let haveCheered = false;
    const newGroups: TurnGroupInfo[] = [];
    for (let g of groups) {
        const newTurns: RaidTurnInfo[]  = [];
        for (let t of g.turns) {
            newTurns.push(t);
            if (t.moveInfo.userID === 1 && t.moveInfo.moveData.name !== "(No Move)") {
                for (const npcID of npcIDs) {
                    const npcMoveInfo = {moveData: {name: (haveCheered ? "Splash" : "Defense Cheer") as MoveName}, userID: npcID, targetID: npcID};
                    const npcMove: RaidTurnInfo = {
                        id: -1,
                        group: t.id,
                        moveInfo: npcMoveInfo,
                        bossMoveInfo: {
                            userID: 0,
                            targetID: npcID,
                            moveData: { name: (t.bossMoveInfo.moveData.name === "(Optimal Move)" ? "(Optimal Move)" : "(Most Damaging)") as MoveName},
                        },
                    };
                    newTurns.push(npcMove);
                    haveCheered = true;
                }
            }
        }
        newGroups.push({
            id: g.id,
            turns: newTurns,
            repeats: g.repeats
        });
    }
    return newGroups;
}

// break groups into "chunks" at points where "(Optimal Move)" is selected for the boss
function splitGroups(groups: TurnGroupInfo[]): TurnGroupInfo[][] {
    const groupsChunks: TurnGroupInfo[][] = [];
    let currentChunk: TurnGroupInfo[] = [];
    for (let i = 0; i < groups.length; i++) {
        let g = groups[i];
        if (
            g.turns.some((t) => t.bossMoveInfo.moveData.name === "(Optimal Move)")
        ) {
            let partialGroup: TurnGroupInfo = {
                id: g.id,
                turns: [],
                repeats: g.repeats,
            }
            for (let j = 0; j < g.turns.length; j++) {
                const t = g.turns[j]
                partialGroup.turns.push(t);
                if (
                    (t.bossMoveInfo.moveData.name === "(Optimal Move)")
                ) {
                    currentChunk.push(partialGroup);
                    groupsChunks.push(currentChunk);
                    partialGroup = {
                        id: g.id,
                        turns: [],
                        repeats: g.repeats,
                    }
                    currentChunk = [];
                } else if (j === g.turns.length-1) {
                    currentChunk.push(partialGroup);
                }
            }
        } else {
            currentChunk.push(g);
            if (i === groups.length-1) {
                groupsChunks.push(currentChunk);
            }
        }
    }
    return groupsChunks;
}

